            "code": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 720 280\" role=\"img\" aria-labelledby=\"d1\">\n  <title id=\"d1\">Perbandingan In-Memory State vs Centralized Redis di Serverless Environment</title>\n  \n  \n  <rect x=\"15\" y=\"20\" width=\"330\" height=\"240\" rx=\"8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-dasharray=\"4 4\"/>\n  <text x=\"30\" y=\"45\" fill=\"#39d5f6\" font-size=\"15\" font-weight=\"bold\">MASALAH: In-Memory State</text>\n  \n  <rect x=\"35\" y=\"65\" width=\"130\" height=\"45\" rx=\"6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1\"/>\n  <text x=\"45\" y=\"92\" fill=\"currentColor\" font-size=\"13\">Lambda Instance A</text>\n  <text x=\"50\" y=\"104\" fill=\"currentColor\" font-size=\"10\">Memory Count: 1</text>\n\n  <rect x=\"195\" y=\"65\" width=\"130\" height=\"45\" rx=\"6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1\"/>\n  <text x=\"205\" y=\"92\" fill=\"currentColor\" font-size=\"13\">Lambda Instance B</text>\n  <text x=\"210\" y=\"104\" fill=\"currentColor\" font-size=\"10\">Memory Count: 1</text>\n\n  <path d=\"M 180 135 L 180 165\" stroke=\"currentColor\" stroke-width=\"1.5\" marker-end=\"url(#arrow)\"/>\n  <text x=\"45\" y=\"185\" fill=\"currentColor\" font-size=\"13\">State terisolasi di tiap instance.</text>\n  <text x=\"45\" y=\"205\" fill=\"currentColor\" font-size=\"13\">Client bisa bypass rate limit</text>\n  <text x=\"45\" y=\"225\" fill=\"currentColor\" font-size=\"13\">dengan menembak IP berbeda.</text>\n\n  \n  <rect x=\"375\" y=\"20\" width=\"330\" height=\"240\" rx=\"8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/>\n  <text x=\"390\" y=\"45\" fill=\"#39d5f6\" font-size=\"15\" font-weight=\"bold\">SOLUSI: Centralized Redis State</text>\n\n  <rect x=\"390\" y=\"65\" width=\"110\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1\"/>\n  <text x=\"400\" y=\"90\" fill=\"currentColor\" font-size=\"13\">Instance A</text>\n\n  <rect x=\"580\" y=\"65\" width=\"110\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1\"/>\n  <text x=\"590\" y=\"90\" fill=\"currentColor\" font-size=\"13\">Instance B</text>\n\n  <path d=\"M 445 105 L 510 160\" stroke=\"currentColor\" stroke-width=\"1.5\"/>\n  <path d=\"M 635 105 L 570 160\" stroke=\"currentColor\" stroke-width=\"1.5\"/>\n\n  <rect x=\"470\" y=\"160\" width=\"140\" height=\"60\" rx=\"6\" fill=\"none\" stroke=\"#39d5f6\" stroke-width=\"2\"/>\n  <text x=\"485\" y=\"185\" fill=\"#39d5f6\" font-size=\"14\" font-weight=\"bold\">Upstash Redis</text>\n  <text x=\"482\" y=\"205\" fill=\"currentColor\" font-size=\"12\">Global State Sync</text>\n</svg>",
