            "children": [
              {
                "mode": "normal",
                "text": "// resilient-service.ts\n\ninterface CircuitBreakerOptions {\n  failureThreshold: number; // Jumlah kegagalan sebelum circuit dibuka\n  cooldownPeriodMs: number; // Waktu tunggu sebelum mencoba lagi\n}\n\nexport class CircuitBreaker {\n  private failureCount = 0;\n  private state: 'CLOSED' | 'OPEN' | 'HALF-OPEN' = 'CLOSED';\n  private nextAttempt = Date.now();\n\n  constructor(private options: CircuitBreakerOptions) {}\n\n  async execute<T>(action: () => Promise<T>, fallback: () => Promise<T>): Promise<T> {\n    if (this.state === 'OPEN') {\n      if (Date.now() > this.nextAttempt) {\n        this.state = 'HALF-OPEN';\n      } else {\n        // Sistem sedang DOWN, langsung panggil fallback tanpa membebankan provider\n        return await fallback();\n      }\n    }\n\n    try {\n      const result = await action();\n      this.reset();\n      return result;\n    } catch (error) {\n      this.handleFailure();\n      console.error(`[CircuitBreaker] Failure caught. State: ${this.state}`, error);\n      return await fallback();\n    }\n  }\n\n  private handleFailure() {\n    this.failureCount++;\n    if (this.failureCount >= this.options.failureThreshold) {\n      this.state = 'OPEN';\n      this.nextAttempt = Date.now() + this.options.cooldownPeriodMs;\n      console.warn(`[CircuitBreaker] Threshold reached. Circuit OPEN for ${this.options.cooldownPeriodMs}ms`);\n    }\n  }\n\n  private reset() {\n    this.failureCount = 0;\n    this.state = 'CLOSED';\n  }\n}\n\n// Contoh Penggunaan saat memanggil Third-Party Recommendation Engine\nconst breaker = new CircuitBreaker({ failureThreshold: 3, cooldownPeriodMs: 30000 });\n\nexport async function getProductRecommendations(userId: string) {\n  return breaker.execute(\n    // Primary Action: Panggil Third-party AI Recommendation API\n    async () => {\n      const response = await fetch(`https://api.external-ai.com/recommend/${userId}`, { timeout: 2000 } as any);\n      if (!response.ok) throw new Error('API External Down');\n      return await response.json();\n    },\n    // Fallback Action: Kembalikan produk terlaris statis jika API utama meledak\n    async () => {\n      console.log(`[Fallback Triggered] Serving static top-selling products for user: ${userId}`);\n      return [\n        { id: 'p1', name: 'Item Terlaris A (Fallback)' },\n        { id: 'p2', name: 'Item Terlaris B (Fallback)' }\n      ];\n    }\n  );\n}",
                "type": "code-highlight",
                "style": "",
                "detail": 0,
                "format": 0,
                "version": 1
              }
            ],
